cat > /tmp/broker.py <<'EOF'
VAULT = {"stripe/key": "sk-live-9f2a"}
ALLOWED = {("stripe", "GET", "/v1/balance")}

class ReadingAgent:
    def __init__(self): self.context = []
    def run(self):
        key = VAULT["stripe/key"]              # the agent now holds it
        self.context.append(f"fetched credential: {key}")
        self.context.append(f"calling stripe with {key}")
        return "balance: 42.00"

def brokered_call(binding, method, path):
    if (binding, method, path) not in ALLOWED:
        return f"DENIED: {binding} {method} {path} is not an allowed intent"
    _key = VAULT["stripe/key"]                 # resolved here, never returned
    return "balance: 42.00"

class BrokeredAgent:
    def __init__(self): self.context = []
    def run(self):
        self.context.append("intent: stripe GET /v1/balance")
        result = brokered_call("stripe", "GET", "/v1/balance")
        self.context.append(f"result: {result}")
        return result

for Agent in (ReadingAgent, BrokeredAgent):
    a = Agent(); a.run()
    leaked = [line for line in a.context if "sk-live" in line]
    print(f"{Agent.__name__}:")
    for line in a.context:
        print(f"    {line}")
    print(f"  -> credential in context: {'YES' if leaked else 'no'}\n")

print("an injected agent tries something else:")
print("   ", brokered_call("stripe", "POST", "/v1/transfers"))
EOF
python3 /tmp/broker.py
